sed -i 's/val scoreEvent by viewModel.lastScorePopup.collectAsState()/val scoreEvent by viewModel.lastScorePopup.collectAsState()\n    \n    \/\/ Shake Animation\n    val shakeAnim = remember { androidx.compose.animation.core.Animatable(0f) }\n    LaunchedEffect(gameState.lastClearedIndices) {\n        if (gameState.lastClearedIndices.isNotEmpty()) {\n            shakeAnim.snapTo(1f)\n            shakeAnim.animateTo(0f, animationSpec = androidx.compose.animation.core.tween(300))\n        }\n    }\n    val shakeOffset = if (shakeAnim.value > 0f) {\n        val maxShake = 10f\n        val dx = (Math.random() - 0.5f).toFloat() * maxShake * shakeAnim.value\n        val dy = (Math.random() - 0.5f).toFloat() * maxShake * shakeAnim.value\n        androidx.compose.ui.unit.IntOffset(dx.toInt(), dy.toInt())\n    } else {\n        androidx.compose.ui.unit.IntOffset.Zero\n    }/g' app/src/main/java/com/example/ui/GameScreen.kt

sed -i 's/                BoardComposable(/                Box(modifier = Modifier.offset { shakeOffset }) {\n                    BoardComposable(/g' app/src/main/java/com/example/ui/GameScreen.kt

sed -i 's/                ScorePopupOverlay(/                }\n                ScorePopupOverlay(/g' app/src/main/java/com/example/ui/GameScreen.kt
